import { createWebDemoBackend } from './demo-backend.js?v=20260901-integrity-1';
import { webRequestTarget } from './demo-routing.js?v=20260901-integrity-1';

const config=Object.freeze({
 apiBaseUrl:String(window.IRESPOND_CONFIG?.apiBaseUrl||'').replace(/\/$/,''),
 oidcIssuer:String(window.IRESPOND_CONFIG?.oidcIssuer||'').replace(/\/$/,''),
 oidcClientId:String(window.IRESPOND_CONFIG?.oidcClientId||''),
 scope:String(window.IRESPOND_CONFIG?.scope||'openid profile'),
 demoMode:window.IRESPOND_CONFIG?.demoMode===true||(!window.IRESPOND_CONFIG?.apiBaseUrl&&!window.IRESPOND_CONFIG?.oidcIssuer&&['localhost','127.0.0.1','::1'].includes(location.hostname))
});
const webDemo=createWebDemoBackend();
if(config.demoMode)webDemo.installUploadFetch();
const state={token:sessionStorage.getItem('irespond.web.access-token')||'',demo:config.demoMode&&sessionStorage.getItem('irespond.web.demo-session')==='1',session:null,page:'',projectId:'',project:null,inviteId:'',inviteProjectId:''};
const $=selector=>document.querySelector(selector),main=$('#main'),nav=$('#primary-nav'),identity=$('#identity-actions'),toast=$('#toast');
const SDGS=Object.freeze(['No Poverty','Zero Hunger','Good Health and Well-being','Quality Education','Gender Equality','Clean Water and Sanitation','Affordable and Clean Energy','Decent Work and Economic Growth','Industry, Innovation and Infrastructure','Reduced Inequalities','Sustainable Cities and Communities','Responsible Consumption and Production','Climate Action','Life Below Water','Life on Land','Peace, Justice and Strong Institutions','Partnerships for the Goals'].map((name,index)=>({id:index+1,name})));
const roleCapabilities={community_verifier:['verification.community','verification.dispute','evidence.review','project.convert','milestone.validate'],institution_verifier:['verification.institution','verification.dispute','project.convert','milestone.validate'],expert_verifier:['verification.expert','verification.dispute','milestone.validate'],impact_auditor:['verification.audit','verification.dispute','milestone.validate'],government_verifier:['verification.government','verification.dispute','milestone.validate'],evidence_reviewer:['evidence.review'],safety_reviewer:['safety.review'],project_steward:['project.convert','project.steward'],trust_safety_admin:['verification.community','verification.institution','verification.expert','verification.audit','verification.government','verification.dispute','verification.reject','evidence.review','project.convert','project.steward','milestone.validate','safety.review']};
function capabilities(){const out=new Set(state.session?['verification.request']:[]);for(const role of state.session?.roles||[])for(const cap of roleCapabilities[role]||[])out.add(cap);return out}
function has(cap){return capabilities().has(cap)}
function esc(value=''){return String(value).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function human(value=''){return String(value).replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase())}
function money(minor,currency){try{return new Intl.NumberFormat(undefined,{style:'currency',currency}).format(Number(minor||0)/100)}catch{return`${currency||''} ${(Number(minor||0)/100).toLocaleString()}`}}
function notify(message){toast.textContent=message;toast.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>toast.classList.remove('show'),2600)}
function errorHTML(message){return`<div class="notice danger">${esc(message)}</div>`}
function signInActions(prefix){const oidc=config.oidcIssuer&&config.oidcClientId?`<button class="button" id="${prefix}-signin">Continue with identity provider</button>`:'';const demo=config.demoMode?`<button class="button secondary" id="${prefix}-demo-signin">Continue with demo account</button>`:'';return`<div class="actions">${oidc}${demo}</div>`}
function authNotice(){return`<section class="panel"><h2>Sign in required</h2><p>This capability uses trusted identity and server authorization. The local demo account is isolated from production identity.</p>${signInActions('page')}</section>`}
function bindSignInActions(prefix){$(`#${prefix}-signin`)?.addEventListener('click',()=>void signIn().catch(e=>notify(e.message)));$(`#${prefix}-demo-signin`)?.addEventListener('click',()=>void demoSignIn().catch(e=>notify(e.message)))}
async function api(path,init={},auth=true){if(webRequestTarget({demoSession:state.demo,demoMode:config.demoMode,apiBaseUrl:config.apiBaseUrl,auth})==='demo')return webDemo.request(path,init);if(!config.apiBaseUrl){if(auth)throw Object.assign(new Error('Sign in is required.'),{status:401});throw new Error('Web API base URL is not configured.')}const headers=new Headers(init.headers||{});headers.set('Accept','application/json');if(init.body&&!headers.has('Content-Type'))headers.set('Content-Type','application/json');if(auth){if(!state.token)throw Object.assign(new Error('Sign in is required.'),{status:401});headers.set('Authorization',`Bearer ${state.token}`)}const response=await fetch(`${config.apiBaseUrl}${path}`,{...init,headers});const text=await response.text();let body=null;try{body=text?JSON.parse(text):null}catch{body=text}if(!response.ok)throw Object.assign(new Error(body?.error||`Request failed (${response.status})`),{status:response.status,body});return body}
const post=(path,body)=>api(path,{method:'POST',body:JSON.stringify(body)}),put=(path,body)=>api(path,{method:'PUT',body:JSON.stringify(body)});
function randomBase64Url(bytes=32){const values=new Uint8Array(bytes);crypto.getRandomValues(values);return btoa(String.fromCharCode(...values)).replaceAll('+','-').replaceAll('/','_').replace(/=+$/,'')}
async function sha256Base64Url(value){const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value));return btoa(String.fromCharCode(...new Uint8Array(digest))).replaceAll('+','-').replaceAll('/','_').replace(/=+$/,'')}
async function discovery(){if(!config.oidcIssuer)throw new Error('OIDC issuer is not configured.');const response=await fetch(`${config.oidcIssuer}/.well-known/openid-configuration`);if(!response.ok)throw new Error('OIDC discovery failed.');return response.json()}
async function signIn(){if(!config.oidcClientId)throw new Error('OIDC client ID is not configured.');const d=await discovery(),verifier=randomBase64Url(48),challenge=await sha256Base64Url(verifier),authState=randomBase64Url(24);sessionStorage.setItem('irespond.web.pkce',verifier);sessionStorage.setItem('irespond.web.state',authState);sessionStorage.setItem('irespond.web.return-hash',location.hash||'#home');const redirectUri=`${location.origin}${location.pathname}`;const url=new URL(d.authorization_endpoint);url.search=new URLSearchParams({client_id:config.oidcClientId,response_type:'code',redirect_uri:redirectUri,scope:config.scope,state:authState,code_challenge:challenge,code_challenge_method:'S256'}).toString();location.assign(url.toString())}
async function demoSignIn(){if(!config.demoMode)throw new Error('Demo sign-in is not enabled.');state.demo=true;state.token='';state.session=webDemo.session;sessionStorage.setItem('irespond.web.demo-session','1');sessionStorage.removeItem('irespond.web.access-token');await route();notify('Signed in with the isolated demo account.')}
async function handleAuthCallback(){const params=new URLSearchParams(location.search),code=params.get('code');if(!code)return;const returned=params.get('state'),expected=sessionStorage.getItem('irespond.web.state'),verifier=sessionStorage.getItem('irespond.web.pkce');if(!returned||returned!==expected||!verifier)throw new Error('OIDC callback state validation failed.');const d=await discovery(),redirectUri=`${location.origin}${location.pathname}`;const response=await fetch(d.token_endpoint,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({grant_type:'authorization_code',client_id:config.oidcClientId,code,redirect_uri:redirectUri,code_verifier:verifier})});if(!response.ok)throw new Error('OIDC token exchange failed.');const token=await response.json();state.demo=false;state.token=token.access_token||'';sessionStorage.removeItem('irespond.web.demo-session');sessionStorage.setItem('irespond.web.access-token',state.token);const hash=sessionStorage.getItem('irespond.web.return-hash')||'#home';['irespond.web.pkce','irespond.web.state','irespond.web.return-hash'].forEach(k=>sessionStorage.removeItem(k));history.replaceState({},'',`${location.pathname}${hash}`)}
async function refreshSession(){if(state.demo){state.session=webDemo.session;return}if(!state.token){state.session=null;return}try{state.session=await api('/v1/session')}catch(error){if(error.status===401){state.token='';state.session=null;sessionStorage.removeItem('irespond.web.access-token')}else throw error}}
function signOut(){state.demo=false;state.token='';state.session=null;sessionStorage.removeItem('irespond.web.demo-session');sessionStorage.removeItem('irespond.web.access-token');renderChrome();location.hash='#home';notify('Signed out from this browser session.')}
function renderChrome(){const items=[['home','Home'],['needs','Needs'],['project','Projects']];if(state.session){items.push(['contributions','Contributions'],['funding','Funding'],['impact','Impact'],['notifications','Notifications'],['privacy','Privacy'],['safety','Safety']);if([...capabilities()].some(v=>v.startsWith('verification.'))||has('evidence.review')||has('project.convert'))items.push(['verification','Verification']);if(has('safety.review'))items.push(['safety-ops','Safety ops'])}nav.innerHTML=items.map(([id,label])=>`<a href="#${id}" ${state.page===id?'aria-current="page"':''}>${label}</a>`).join('');identity.innerHTML=state.session?`<span class="subject">${esc(state.session.subject)}${state.demo?' · Demo':''}</span><button class="button ghost" id="sign-out">Sign out</button>`:signInActions('header');bindSignInActions('header');$('#sign-out')?.addEventListener('click',signOut)}
async function requireAuth(){if(state.session)return true;main.innerHTML=authNotice();bindSignInActions('page');return false}
async function route(){state.page=(location.hash||'#home').slice(1).split('?')[0]||'home';renderChrome();main.innerHTML='<div class="empty"><span class="loading"></span> Loading…</div>';try{const fn={home:renderHome,needs:renderNeeds,verification:renderVerification,project:renderProject,contributions:renderContributions,funding:renderFunding,impact:renderImpact,notifications:renderNotifications,privacy:renderPrivacy,safety:renderSafety,'safety-ops':renderSafetyOps}[state.page]||renderHome;await fn();if(state.page==='needs')bindSdgDropdown();bindSignInActions('page')}catch(e){main.innerHTML=`<section class="panel"><h2>Unable to load</h2>${errorHTML(e.message||String(e))}</section>`}finally{renderChrome();main.focus({preventScroll:true})}}
async function renderHome(){let platform={lifecycle:['see','report','verify','diagnose','project','mobilise','execute','measure','maintain','replicate']};try{platform=await api('/v1/platform',{},false)}catch{}main.innerHTML=`<section class="hero"><div class="hero-copy"><span class="eyebrow">SEE IT · OWN IT · SOLVE IT</span><h1>Turn what your community sees into action it can prove.</h1><p>Report needs, verify responsibly, mobilise time and resources, execute governed projects and keep evidence of what changed.</p><div class="hero-actions"><a class="button gold" href="#needs">Discover or report a need</a><a class="button secondary" href="#project">Open Project Room</a></div></div><aside class="hero-aside"><div class="metric"><span>Product doctrine</span><strong>3P</strong><p>Place · Position · Possessions / capabilities</p></div><div class="metric"><span>Action lifecycle</span><strong>${platform.lifecycle?.length||10}</strong><p>${(platform.lifecycle||[]).map(human).join(' → ')}</p></div><div class="metric"><span>Access</span><strong>${state.session?'Role-aware':'Public'}</strong><p>${state.session?'Global roles plus per-project permission envelopes.':'Public discovery; protected actions require trusted identity.'}</p></div></aside></section><section class="section"><div class="grid"><a class="card card-link" href="#needs"><h3>Community discovery</h3><p>Nearby needs, reporting and evidence.</p></a><a class="card card-link" href="#project"><h3>Action Projects</h3><p>Milestones, contributions, roles and maintained outcomes.</p></a><a class="card card-link" href="#funding"><h3>Transparent funding</h3><p>Pledges remain distinct from regulated money settlement.</p></a></div></section>`}
function sdgDropdownHTML(){return`<div class="field full"><label id="sdg-dropdown-label">Sustainable Development Goals</label><details class="sdg-dropdown"><summary aria-labelledby="sdg-dropdown-label sdg-summary"><span id="sdg-summary">Select one or more SDGs</span><span aria-hidden="true">⌄</span></summary><input type="hidden" name="sdgTags" value=""><div class="sdg-options">${SDGS.map(goal=>`<label><input type="checkbox" name="sdgTagOption" value="${goal.id}"><strong>${goal.id}</strong><span>${esc(goal.name)}</span></label>`).join('')}</div></details><small class="field-help">Optional. Select any goals this observation may affect.</small></div>`}
function bindSdgDropdown(){const legacy=$('#report-form input[name="sdgTags"]');if(legacy&&!legacy.closest('.sdg-dropdown'))legacy.closest('.field').outerHTML=sdgDropdownHTML();const summary=$('#sdg-summary'),hidden=$('#report-form input[name="sdgTags"]'),options=[...document.querySelectorAll('input[name="sdgTagOption"]')];if(!summary||!hidden)return;const update=()=>{const selected=options.filter(input=>input.checked).map(input=>input.value),value=selected.join(',');hidden.value=value;hidden.setAttribute('value',value);summary.textContent=selected.length?`${selected.length} selected · ${selected.map(item=>`SDG ${item}`).join(', ')}`:'Select one or more SDGs'};options.forEach(input=>input.addEventListener('change',update));update()}
async function renderNeeds(){main.innerHTML=`<section class="section-head"><div><span class="eyebrow" style="color:var(--brand-2)">COMMUNITY DISCOVERY</span><h2>See what needs attention—or report what you observe.</h2><p>A report is not automatically verified fact, project or fundraising campaign.</p></div></section><div class="grid two"><section class="panel"><h3>Discover nearby</h3><form id="nearby-form" class="form-grid"><div class="field"><label>Latitude</label><input name="lat" inputmode="decimal" required></div><div class="field"><label>Longitude</label><input name="lng" inputmode="decimal" required></div><div class="field"><label>Radius km</label><input name="radiusKm" value="25" inputmode="decimal" required></div><div class="field"><label>&nbsp;</label><button class="button" type="submit">Find needs</button></div></form><div id="nearby-results" class="list"></div></section><section class="panel"><h3>Report a community need</h3><form id="report-form" class="form-grid"><div class="field full"><label>Title</label><input name="title" required></div><div class="field full"><label>Description</label><textarea name="description" required></textarea></div><div class="field"><label>Category</label><input name="category" value="community"></div><div class="field"><label>SDG tags</label><input name="sdgTags" placeholder="6, 11, 17"></div><div class="field"><label>Latitude</label><input name="latitude" inputmode="decimal" required></div><div class="field"><label>Longitude</label><input name="longitude" inputmode="decimal" required></div><div class="field full"><button class="button gold" type="submit">Submit observation</button></div></form><div id="report-result"></div></section></div><section class="panel"><h3>Follow a need into its Action Project</h3><form id="need-project-lookup" class="form-grid"><div class="field"><label>Need ID</label><input name="needId" required></div><div class="field"><label>&nbsp;</label><button class="button secondary" type="submit">Find linked project</button></div></form><div id="need-project-result"></div></section><section class="panel"><h3>Evidence upload</h3>${state.session?`<form id="evidence-form" class="form-grid"><div class="field"><label>Need ID</label><input name="needId" required></div><div class="field"><label>Evidence file</label><input name="file" type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/quicktime" required></div><div class="field full"><button class="button" type="submit">Upload evidence safely</button></div></form>`:authNotice()}</section>`;$('#page-signin')?.addEventListener('click',()=>void signIn().catch(e=>notify(e.message)));$('#nearby-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),box=$('#nearby-results');box.innerHTML='<span class="loading"></span>';try{const items=await api(`/v1/needs?lat=${encodeURIComponent(f.get('lat'))}&lng=${encodeURIComponent(f.get('lng'))}&radiusKm=${encodeURIComponent(f.get('radiusKm'))}`,{},false);box.innerHTML=items.length?items.map(n=>`<article class="list-item"><header><h3>${esc(n.title)}</h3><span class="badge">${human(n.verificationState)}</span></header><p>${esc(n.description||'')}</p><button class="button secondary inspect-need" data-id="${esc(n.id)}">Inspect need</button></article>`).join(''):'<div class="empty">No nearby needs found.</div>';box.querySelectorAll('.inspect-need').forEach(button=>button.onclick=async()=>{try{const need=await api(`/v1/needs/${encodeURIComponent(button.dataset.id)}`,{},false);notify(`${need.title}: ${human(need.verificationState)}`)}catch(err){notify(err.message)}})}catch(err){box.innerHTML=errorHTML(err.message)}};$('#report-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),out=$('#report-result');try{const sdg=String(f.get('sdgTags')||'').split(',').map(v=>Number(v.trim())).filter(v=>Number.isInteger(v)&&v>=1&&v<=17);const created=await api('/v1/needs',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({title:f.get('title'),description:f.get('description'),category:f.get('category'),latitude:Number(f.get('latitude')),longitude:Number(f.get('longitude')),sdgTags:sdg})},false);out.innerHTML=`<div class="notice success">Observation created: <strong>${esc(created.id)}</strong>. It remains ${human(created.verificationState)}.</div>`}catch(err){out.innerHTML=errorHTML(err.message)}};$('#need-project-lookup').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),box=$('#need-project-result'),needId=String(f.get('needId'));try{const project=await api(`/v1/needs/${encodeURIComponent(needId)}/project`,{},false);box.innerHTML=`<div class="notice success"><strong>${esc(project.title||project.id)}</strong><br><button class="button secondary" id="open-linked-project">Open Project Room</button></div>`;$('#open-linked-project').onclick=()=>{state.projectId=project.id;location.hash='#project'}}catch(err){box.innerHTML=errorHTML(err.message)}};$('#evidence-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),file=f.get('file'),needId=String(f.get('needId')||'');if(!(file instanceof File))return;try{const digest=await crypto.subtle.digest('SHA-256',await file.arrayBuffer()),sha256Hex=[...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('');const upload=await post(`/v1/needs/${encodeURIComponent(needId)}/evidence/uploads`,{contentType:file.type,sizeBytes:file.size,sha256Hex});const putResponse=await fetch(upload.uploadUrl,{method:upload.method||'PUT',headers:{...(upload.headers||{}),'Content-Type':file.type},body:file});if(!putResponse.ok)throw new Error(`Object upload failed (${putResponse.status})`);await post(`/v1/needs/${encodeURIComponent(needId)}/evidence/${encodeURIComponent(upload.evidenceId)}/complete`,{});notify('Evidence uploaded and submitted for review.')}catch(err){notify(err.message)}})}
function verificationTransitionAllowed(current,target){if(target==='disputed'||target==='rejected')return current!=='rejected';return({observed:['verification_requested'],verification_requested:['community_confirmed','institution_confirmed','expert_confirmed'],community_confirmed:['independently_audited','government_confirmed'],institution_confirmed:['independently_audited','government_confirmed'],expert_confirmed:['independently_audited','government_confirmed'],disputed:['verification_requested']}[current]||[]).includes(target)}
function verificationButtons(currentState){const caps=capabilities();return[['verification_requested','Request verification','verification.request'],['community_confirmed','Community confirm','verification.community'],['institution_confirmed','Institution confirm','verification.institution'],['expert_confirmed','Expert confirm','verification.expert'],['independently_audited','Independent audit','verification.audit'],['government_confirmed','Government confirm','verification.government'],['disputed','Dispute','verification.dispute'],['rejected','Reject','verification.reject']].filter(([state,,cap])=>caps.has(cap)&&verificationTransitionAllowed(currentState,state))}
async function renderVerification(){if(!await requireAuth())return;main.innerHTML=`<section class="section-head"><div><span class="eyebrow" style="color:var(--brand-2)">VERIFICATION</span><h2>Use only the authority attached to your trusted role.</h2></div></section><section class="panel"><form id="verify-load" class="form-grid"><div class="field"><label>Need ID</label><input name="needId" required></div><div class="field"><label>&nbsp;</label><button class="button" type="submit">Load need</button></div></form><div id="verify-need"></div></section>${has('evidence.review')?`<section class="panel"><h3>Evidence moderation</h3><form id="evidence-review" class="form-grid"><div class="field"><label>Evidence ID</label><input name="evidenceId" required></div><div class="field"><label>Decision</label><select name="decision"><option value="available">Available</option><option value="quarantined">Quarantined</option><option value="rejected">Rejected</option></select></div><div class="field full"><button class="button" type="submit">Record decision</button></div></form></section><section class="panel"><h3>Approved evidence access</h3><form id="evidence-access" class="form-grid"><div class="field"><label>Need ID</label><input name="needId" required></div><div class="field"><label>Evidence ID</label><input name="evidenceId" required></div><div class="field full"><button class="button secondary" type="submit">Request signed URL</button></div></form><div id="evidence-access-result"></div></section>`:''}`;$('#verify-load').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),needId=String(f.get('needId')),box=$('#verify-need');try{const need=await api(`/v1/needs/${encodeURIComponent(needId)}`,{},false);box.innerHTML=`<article class="list-item"><header><h3>${esc(need.title)}</h3><span class="badge">${human(need.verificationState)}</span></header><p>${esc(need.description||'')}</p><div class="actions">${verificationButtons(need.verificationState).map(([value,label])=>`<button class="button secondary verify-action" data-state="${value}" data-id="${esc(need.id)}">${label}</button>`).join('')}</div>${has('project.convert')?`<form id="convert-project" class="form-grid"><input type="hidden" name="needId" value="${esc(need.id)}"><div class="field"><label>Project title</label><input name="title" value="${esc(need.title)}" required></div><div class="field"><label>Owner community ID</label><input name="ownerCommunityId" required></div><div class="field full"><label>Description</label><textarea name="description">${esc(need.description||'')}</textarea></div><div class="field full"><button class="button" type="submit">Create Action Project</button></div></form>`:''}</article>`;box.querySelectorAll('.verify-action').forEach(button=>button.onclick=async()=>{try{await post(`/v1/needs/${encodeURIComponent(button.dataset.id)}/verification`,{state:button.dataset.state});notify('Verification state updated.');e.currentTarget.requestSubmit()}catch(err){notify(err.message)}});$('#convert-project')?.addEventListener('submit',async ev=>{ev.preventDefault();const data=new FormData(ev.currentTarget);try{const project=await post(`/v1/needs/${encodeURIComponent(data.get('needId'))}/project`,{title:data.get('title'),description:data.get('description'),ownerCommunityId:data.get('ownerCommunityId')});state.projectId=project.id;notify('Action Project created.');location.hash='#project'}catch(err){notify(err.message)}})}catch(err){box.innerHTML=errorHTML(err.message)}};$('#evidence-review')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await post(`/v1/evidence/${encodeURIComponent(f.get('evidenceId'))}/review`,{decision:f.get('decision')});notify('Evidence decision recorded.')}catch(err){notify(err.message)}});$('#evidence-access')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),out=$('#evidence-access-result');try{const access=await api(`/v1/needs/${encodeURIComponent(f.get('needId'))}/evidence/${encodeURIComponent(f.get('evidenceId'))}/access`);out.innerHTML=`<div class="notice success"><a href="${esc(access.url)}" target="_blank" rel="noreferrer">Open approved evidence</a></div>`}catch(err){out.innerHTML=errorHTML(err.message)}})}
const emptyPermissions={canManageProject:false,canManageMilestones:false,canValidateMilestones:false,canManageRoles:false,canManageContributions:false,canPublishContributionNeeds:false,canManageFunding:false};
async function renderProject(){main.innerHTML=`<section class="section-head"><div><span class="eyebrow" style="color:var(--brand-2)">ACTION PROJECTS</span><h2>Govern delivery from verified need to maintained outcome.</h2><p>Project controls come only from the server permission envelope.</p></div></section><section class="panel"><form id="project-load" class="form-grid"><div class="field"><label>Project ID</label><input name="projectId" value="${esc(state.projectId)}" required></div><div class="field"><label>&nbsp;</label><button class="button" type="submit">Open Project Room</button></div></form><div id="project-result"></div></section>`;$('#project-load').onsubmit=async e=>{e.preventDefault();const id=String(new FormData(e.currentTarget).get('projectId')),box=$('#project-result');state.projectId=id;try{const detail=state.session?await api(`/v1/projects/${encodeURIComponent(id)}`):await api(`/v1/projects/${encodeURIComponent(id)}`,{},false);state.project=detail;const permissions=detail.permissions||emptyPermissions;let offers=[];if(state.session&&permissions.canManageContributions)offers=await api(`/v1/projects/${encodeURIComponent(id)}/contribution-offers`);box.innerHTML=projectHTML(detail,{permissions,offers});bindProjectActions(id,{permissions})}catch(err){box.innerHTML=errorHTML(err.message)}};if(state.projectId)$('#project-load').requestSubmit()}
function milestoneTransitionForm(m,state,label){return`<form class="milestone-transition" data-id="${esc(m.id)}"><input name="state" type="hidden" value="${state}"><button class="button secondary" type="submit">${label}</button></form>`}
function milestoneControls(m,p){if(p.canValidateMilestones&&m.status==='submitted')return milestoneTransitionForm(m,'validated','Validate submitted milestone')+(p.canManageMilestones&&m.status==='submitted'?milestoneTransitionForm(m,'cancelled','Cancel submitted milestone'):'');if(p.canManageMilestones&&m.status==='submitted')return milestoneTransitionForm(m,'cancelled','Cancel submitted milestone');if(!p.canManageMilestones)return'';const next=({planned:'ready',ready:'in_progress',in_progress:'submitted',blocked:'in_progress'})[m.status];return next?`<form class="milestone-transition" data-id="${esc(m.id)}"><div class="field"><label>Next state</label><input name="state" value="${next}" required></div><button class="button secondary" type="submit">Apply milestone transition</button></form>`:''}
function offerControls(o){const offerState=o.status||o.state||'offered';if(offerState==='offered')return`<div class="actions"><button class="button secondary offer-decision" data-offer="${esc(o.id)}" data-decision="accepted">Accept</button><button class="button secondary offer-decision" data-offer="${esc(o.id)}" data-decision="declined">Decline</button></div>`;if(offerState==='accepted')return`<div class="actions"><button class="button offer-fulfill" data-offer="${esc(o.id)}">Mark fulfilled</button></div>`;return''}
function projectHTML(detail,authority){const p=authority.permissions||emptyPermissions;return`<div class="stack"><article class="list-item"><header><h3>${esc(detail.project.title)}</h3><span class="badge">${human(detail.project.status)}</span></header><p>${esc(detail.project.description||'')}</p><small>Project ${esc(detail.project.id)}</small></article><div class="grid two"><section class="card"><h3>Milestones</h3><div class="list">${detail.milestones.length?detail.milestones.map(m=>`<div class="list-item"><header><strong>${m.sequence}. ${esc(m.title)}</strong><span class="badge">${human(m.status)}</span></header>${milestoneControls(m,p)}</div>`).join(''):'<div class="empty">No milestones yet.</div>'}</div></section><section class="card"><h3>Contribution needs</h3><div class="list">${detail.contributionNeeds.length?detail.contributionNeeds.map(n=>`<div class="list-item"><strong>${human(n.kind)}</strong><p>${esc(n.description)}</p><span class="badge">${human(n.status)}</span>${state.session?`<form class="offer-form" data-need="${esc(n.id)}"><div class="field"><label>Your offer</label><textarea name="note"></textarea></div><div class="field"><label>Availability</label><input name="availabilityNote"></div><button class="button secondary" type="submit">I can help</button></form>`:''}</div>`).join(''):'<div class="empty">Contribution plan pending.</div>'}</div></section></div>${p.canManageContributions?`<section class="panel"><h3>Contribution offer review</h3><div class="list">${authority.offers.length?authority.offers.map(o=>`<div class="list-item"><header><strong>${esc(o.contributorId)}</strong><span class="badge">${human(o.status||o.state||'offered')}</span></header><p>${esc(o.note||'')}</p>${offerControls(o)}</div>`).join(''):'<div class="empty">No reviewable offers.</div>'}</div></section>`:''}${stewardHTML(detail,p)}<div class="notice">Visible controls mirror the authenticated Project Room permission envelope; every write is re-authorized by the API.</div></div>`}
function stewardHTML(detail,p){const cards=[];if(p.canManageMilestones)cards.push(`<form id="milestone-form" class="card form-grid"><h3 class="field full">Add milestone</h3><div class="field full"><label>Title</label><input name="title" required></div><div class="field full"><label>Description</label><textarea name="description"></textarea></div><div class="field"><label>Sequence</label><input name="sequence" type="number" min="1" value="${detail.milestones.length+1}"></div><div class="field"><label>Target date/time</label><input name="targetAt" type="datetime-local"></div><div class="field full"><button class="button" type="submit">Add milestone</button></div></form>`);if(p.canPublishContributionNeeds)cards.push(`<form id="contribution-need-form" class="card form-grid"><h3 class="field full">Publish contribution need</h3><div class="field"><label>Kind</label><input name="kind" value="time" required></div><div class="field"><label>Quantity note</label><input name="quantityNote"></div><div class="field full"><label>Description</label><textarea name="description" required></textarea></div><div class="field full"><button class="button" type="submit">Publish need</button></div></form>`);if(p.canManageRoles)cards.push(`<form id="role-invite-form" class="card form-grid"><h3 class="field full">Invite project role</h3><div class="field"><label>Identity / actor ID</label><input name="actorId" value="${state.demo?esc(state.session?.subject||''):''}" required></div><div class="field"><label>Role</label><select name="role"><option>project_manager</option><option>community_steward</option><option>verifier</option><option>volunteer_lead</option><option>procurement_lead</option><option>maintenance_owner</option></select></div><div class="field full"><button class="button" type="submit">Create invitation</button></div><p id="role-invite-result" class="notice field full" ${state.inviteProjectId===detail.project.id?'':'hidden'}>${state.inviteProjectId===detail.project.id?`Invitation <code>${esc(state.inviteId)}</code> is ready. Open Contributions to accept it.`:''}</p></form>`);if(p.canManageProject)cards.push(`<form id="project-transition-form" class="card form-grid"><h3 class="field full">Project lifecycle</h3><div class="field full"><label>Next state</label><input name="state" required></div><div class="field full"><button class="button" type="submit">Apply transition</button></div></form>`);return cards.length?`<section class="panel"><h3>Server-authorized stewardship</h3><div class="grid two">${cards.join('')}</div></section>`:''}
function bindProjectActions(projectId,authority){const p=authority.permissions||emptyPermissions;document.querySelectorAll('.offer-form').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await post(`/v1/projects/${encodeURIComponent(projectId)}/contribution-needs/${encodeURIComponent(e.currentTarget.dataset.need)}/offers`,{note:f.get('note'),availabilityNote:f.get('availabilityNote')});notify('Contribution offer recorded.')}catch(err){notify(err.message)}});if(p.canManageContributions){document.querySelectorAll('.offer-decision').forEach(button=>button.onclick=async()=>{try{await post(`/v1/projects/${encodeURIComponent(projectId)}/contribution-offers/${encodeURIComponent(button.dataset.offer)}/decision`,{decision:button.dataset.decision,closeNeed:false});notify('Offer decision recorded.');$('#project-load').requestSubmit()}catch(err){notify(err.message)}});document.querySelectorAll('.offer-fulfill').forEach(button=>button.onclick=async()=>{try{await post(`/v1/projects/${encodeURIComponent(projectId)}/contribution-offers/${encodeURIComponent(button.dataset.offer)}/fulfill`,{});notify('Contribution marked fulfilled.');$('#project-load').requestSubmit()}catch(err){notify(err.message)}})}document.querySelectorAll('.milestone-transition').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await post(`/v1/projects/${encodeURIComponent(projectId)}/milestones/${encodeURIComponent(e.currentTarget.dataset.id)}/transition`,{state:f.get('state')});notify('Milestone state updated.');$('#project-load').requestSubmit()}catch(err){notify(err.message)}});$('#milestone-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await post(`/v1/projects/${encodeURIComponent(projectId)}/milestones`,{title:f.get('title'),description:f.get('description'),sequence:Number(f.get('sequence')),targetAt:f.get('targetAt')?new Date(f.get('targetAt')).toISOString():null});notify('Milestone added.');$('#project-load').requestSubmit()}catch(err){notify(err.message)}});$('#contribution-need-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await post(`/v1/projects/${encodeURIComponent(projectId)}/contribution-needs`,{kind:f.get('kind'),description:f.get('description'),quantityNote:f.get('quantityNote')});notify('Contribution need published.');$('#project-load').requestSubmit()}catch(err){notify(err.message)}});$('#role-invite-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const invite=await post(`/v1/projects/${encodeURIComponent(projectId)}/roles/invite`,{actorId:f.get('actorId'),role:f.get('role')});state.inviteId=String(invite.id||'');state.inviteProjectId=projectId;const result=$('#role-invite-result');result.hidden=false;result.innerHTML=`Invitation <code>${esc(state.inviteId)}</code> is ready. Open Contributions to accept it.`;notify('Project role invitation created and ready to accept.')}catch(err){notify(err.message)}});$('#project-transition-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await post(`/v1/projects/${encodeURIComponent(projectId)}/transition`,{state:f.get('state')});notify('Project state updated.');$('#project-load').requestSubmit()}catch(err){notify(err.message)}})}
async function renderContributions(){if(!await requireAuth())return;const items=await api('/v1/me/contribution-offers');main.innerHTML=`<section class="section-head"><div><span class="eyebrow" style="color:var(--brand-2)">CONTRIBUTIONS</span><h2>Time, skills, materials, access and care are first-class responses.</h2></div></section><section class="panel"><h3>My contribution offers</h3><div class="list">${items.length?items.map(o=>`<article class="list-item"><header><h3>${human(o.kind||'contribution')} · project ${esc(o.projectId)}</h3><span class="badge">${human(o.status||o.state)}</span></header><p>${esc(o.note||'')}</p>${['offered','pending'].includes(o.status||o.state)?`<button class="button secondary withdraw-offer" data-id="${esc(o.id)}">Withdraw open offer</button>`:''}</article>`).join(''):'<div class="empty">No contribution offers yet.</div>'}</div></section><section class="panel"><h3>Accept a project role invitation</h3><form id="role-accept" class="form-grid"><div class="field"><label>Invitation ID</label><input name="inviteId" value="${esc(state.inviteId)}" required></div><div class="field"><label>&nbsp;</label><button class="button" type="submit">Accept role</button></div></form></section>`;document.querySelectorAll('.withdraw-offer').forEach(button=>button.onclick=async()=>{try{await post(`/v1/contribution-offers/${encodeURIComponent(button.dataset.id)}/withdraw`,{});notify('Offer withdrawn.');await renderContributions()}catch(e){notify(e.message)}});$('#role-accept').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const accepted=await post(`/v1/project-role-invites/${encodeURIComponent(f.get('inviteId'))}/accept`,{});state.projectId=accepted.projectId||state.projectId;state.inviteId='';state.inviteProjectId='';e.currentTarget.reset();notify('Project role accepted.')}catch(err){notify(err.message)}}}
async function loadFundingPlan(projectId){try{return await api(`/v1/projects/${encodeURIComponent(projectId)}/funding`)}catch(error){if(error.status===404)return null;throw error}}
async function renderFunding(){if(!await requireAuth())return;const mine=await api('/v1/me/funding/pledges');main.innerHTML=`<section class="section-head"><div><span class="eyebrow" style="color:var(--brand-2)">FUNDING</span><h2>Transparent commitments without overstating settlement.</h2></div></section><div class="grid two"><section class="panel"><h3>My pledges</h3><div class="list">${mine.length?mine.map(p=>`<article class="list-item"><header><h3>${money(p.amountMinor,p.currency)}</h3><span class="badge">${human(p.status)}</span></header><p>Project ${esc(p.projectId)}</p>${p.status==='pledged'?`<button class="button secondary cancel-pledge" data-id="${esc(p.id)}">Cancel open pledge</button>`:''}</article>`).join(''):'<div class="empty">No funding pledges yet.</div>'}</div></section><section class="panel"><h3>Project funding plan</h3><form id="funding-load" class="form-grid"><div class="field"><label>Project ID</label><input name="projectId" value="${esc(state.projectId)}" required></div><div class="field"><label>&nbsp;</label><button class="button" type="submit">Load plan</button></div></form><div id="funding-result"></div></section></div>`;document.querySelectorAll('.cancel-pledge').forEach(button=>button.onclick=async()=>{try{await post(`/v1/funding/pledges/${encodeURIComponent(button.dataset.id)}/cancel`,{});notify('Pledge cancelled.');await renderFunding()}catch(e){notify(e.message)}});$('#funding-load').onsubmit=async e=>{e.preventDefault();const id=String(new FormData(e.currentTarget).get('projectId')),box=$('#funding-result');state.projectId=id;try{const[plan,project]=await Promise.all([loadFundingPlan(id),api(`/v1/projects/${encodeURIComponent(id)}`)]);const p=project.permissions||emptyPermissions;const currency=plan?.currency||'CAD';let managerPledges=[];if(p.canManageFunding)managerPledges=await api(`/v1/projects/${encodeURIComponent(id)}/funding/pledges`);box.innerHTML=`${plan?`<div class="metric"><span>Target</span><strong>${money(plan.targetMinor,currency)}</strong><p>${money(plan.pledgedMinor,currency)} pledged · ${money(plan.confirmedMinor,currency)} externally confirmed</p></div><form id="make-pledge" class="form-grid"><div class="field"><label>Amount (${esc(currency)})</label><input name="amount" inputmode="decimal" required></div><div class="field"><label>Contribution class</label><select name="contributionClass"><option value="external_donation">External donation</option><option value="community_counterpart">Community counterpart</option><option value="matching_commitment">Matching commitment</option></select></div><div class="field full"><button class="button" type="submit">Record pledge</button></div></form>`:'<div class="empty">No funding plan has been published yet.</div>'}${p.canManageFunding?`<form id="funding-manage" class="form-grid"><div class="field"><label>Currency</label><input name="currency" value="${esc(currency)}" maxlength="3"></div><div class="field"><label>Total target</label><input name="target" value="${(plan?.targetMinor||0)/100}" inputmode="decimal"></div><div class="field"><label>Community counterpart</label><input name="counterpart" value="${(plan?.communityCounterpartMinor||0)/100}" inputmode="decimal"></div><div class="field"><label>&nbsp;</label><button class="button secondary" type="submit">Update plan</button></div></form><div class="list">${managerPledges.map(x=>`<div class="list-item"><strong>${esc(x.contributorId)}</strong> · ${money(x.amountMinor,x.currency)} · ${human(x.status)}</div>`).join('')}</div>`:''}`;$('#make-pledge')?.addEventListener('submit',async ev=>{ev.preventDefault();const data=new FormData(ev.currentTarget);try{await post(`/v1/projects/${encodeURIComponent(id)}/funding/pledges`,{contributionClass:data.get('contributionClass'),amountMinor:Math.round(Number(data.get('amount'))*100)});notify('Pledge recorded; no money has been moved.')}catch(err){notify(err.message)}});$('#funding-manage')?.addEventListener('submit',async ev=>{ev.preventDefault();const data=new FormData(ev.currentTarget);try{await put(`/v1/projects/${encodeURIComponent(id)}/funding`,{currency:String(data.get('currency')).toUpperCase(),targetMinor:Math.round(Number(data.get('target'))*100),communityCounterpartMinor:Math.round(Number(data.get('counterpart'))*100)});notify('Funding plan updated.');e.currentTarget.requestSubmit()}catch(err){notify(err.message)}})}catch(err){box.innerHTML=errorHTML(err.message)}};if(state.projectId)$('#funding-load').requestSubmit()}
async function renderImpact(){if(!await requireAuth())return;const p=await api('/v1/me/impact-passport');main.innerHTML=`<section class="section-head"><div><span class="eyebrow" style="color:var(--brand-2)">IMPACT PASSPORT</span><h2>Your response, evidenced.</h2></div></section><div class="grid four"><div class="metric"><span>Projects led</span><strong>${p.projectsLed||0}</strong></div><div class="metric"><span>Completed</span><strong>${p.projectsCompleted||0}</strong></div><div class="metric"><span>Verifications</span><strong>${p.verifications||0}</strong></div><div class="metric"><span>Fulfilled responses</span><strong>${p.fulfilledContributions||0}</strong></div></div><section class="panel"><h3>SDGs touched</h3><div class="role-row">${(p.sdgs||[]).length?p.sdgs.map(n=>`<span class="badge">SDG ${n}</span>`).join(''):'No verified project SDGs yet.'}</div></section>`}
async function renderNotifications(){if(!await requireAuth())return;const[items,prefs]=await Promise.all([api('/v1/me/notifications'),api('/v1/me/notification-preferences')]);main.innerHTML=`<section class="section-head"><div><span class="eyebrow" style="color:var(--brand-2)">NOTIFICATIONS</span><h2>Updates with user-controlled delivery.</h2></div></section><div class="grid two"><section class="panel"><h3>Inbox</h3><div class="list">${items.length?items.map(n=>`<article class="list-item"><header><h3>${esc(n.title)}</h3>${n.readAt?'':'<span class="badge">New</span>'}</header><p>${esc(n.body||'')}</p>${n.readAt?'':`<button class="button secondary mark-read" data-id="${esc(n.id)}">Mark read</button>`}</article>`).join(''):'<div class="empty">No notifications.</div>'}</div></section><section class="panel"><h3>Preferences</h3><form id="notification-prefs" class="form-grid">${Object.entries(prefs||{}).filter(([,v])=>typeof v==='boolean').map(([key,value])=>`<label class="field"><span>${human(key)}</span><select name="${esc(key)}"><option value="true" ${value?'selected':''}>On</option><option value="false" ${!value?'selected':''}>Off</option></select></label>`).join('')}<div class="field full"><button class="button" type="submit">Save preferences</button></div></form></section></div>`;document.querySelectorAll('.mark-read').forEach(button=>button.onclick=async()=>{try{await post(`/v1/me/notifications/${encodeURIComponent(button.dataset.id)}/read`,{});await renderNotifications()}catch(e){notify(e.message)}});$('#notification-prefs').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),body={...prefs};for(const[key]of f.entries())body[key]=f.get(key)==='true';try{await put('/v1/me/notification-preferences',body);notify('Notification preferences saved.')}catch(err){notify(err.message)}}}
async function renderPrivacy(){if(!await requireAuth())return;const[consents,requests]=await Promise.all([api('/v1/me/privacy/consents'),api('/v1/me/privacy/requests')]),values=Object.fromEntries(consents.map(c=>[c.purpose,c]));main.innerHTML=`<section class="section-head"><div><span class="eyebrow" style="color:var(--brand-2)">PRIVACY & DIGNITY</span><h2>Your data, your choices.</h2></div></section><div class="grid two"><section class="panel"><h3>Optional data uses</h3>${['impact-research','product-improvement'].map(p=>`<form class="consent-form list-item" data-purpose="${p}"><header><strong>${human(p)}</strong><select name="granted"><option value="true" ${values[p]?.granted?'selected':''}>Allowed</option><option value="false" ${!values[p]?.granted?'selected':''}>Not allowed</option></select></header><button class="button secondary" type="submit">Save choice</button></form>`).join('')}</section><section class="panel"><h3>Exercise data rights</h3><div class="actions">${['access','export','correction','deletion'].map(type=>`<button class="button secondary privacy-request" data-type="${type}">${human(type)}</button>`).join('')}</div><h3>Request history</h3><div class="list">${requests.length?requests.map(r=>`<div class="list-item"><header><strong>${human(r.type)}</strong><span class="badge">${human(r.status)}</span></header></div>`).join(''):'<div class="empty">No privacy requests yet.</div>'}</div></section></div>`;document.querySelectorAll('.consent-form').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await put(`/v1/me/privacy/consents/${encodeURIComponent(e.currentTarget.dataset.purpose)}`,{granted:f.get('granted')==='true',policyVersion:'2026-08'});notify('Privacy choice saved.')}catch(err){notify(err.message)}});document.querySelectorAll('.privacy-request').forEach(button=>button.onclick=async()=>{try{await post('/v1/me/privacy/requests',{type:button.dataset.type});notify('Privacy request recorded.');await renderPrivacy()}catch(e){notify(e.message)}})}
async function renderSafety(){if(!await requireAuth())return;const items=await api('/v1/me/safety/reports');main.innerHTML=`<section class="section-head"><div><span class="eyebrow" style="color:var(--danger)">SAFETY & APPEALS</span><h2>Confidential reporting with a visible follow-up trail.</h2></div></section><div class="grid two"><section class="panel"><h3>Report a concern</h3><form id="safety-report" class="form-grid"><div class="field"><label>Subject type</label><input name="subjectType" value="platform" required></div><div class="field"><label>Subject ID</label><input name="subjectId" value="general" required></div><div class="field"><label>Reason</label><select name="reason"><option>fraud</option><option>privacy</option><option>harassment</option><option>unsafe_activity</option><option>child_safety</option><option>financial_abuse</option><option>other</option></select></div><div class="field full"><label>Details</label><textarea name="details"></textarea></div><div class="field full"><button class="button danger" type="submit">Submit confidential report</button></div></form></section><section class="panel"><h3>Your reports</h3><div class="list">${items.length?items.map(r=>`<article class="list-item"><header><h3>${human(r.reason)}</h3><span class="badge danger">${human(r.status)}</span></header><p>${esc(r.details||'')}</p><form class="appeal-form" data-id="${esc(r.id)}"><div class="field"><label>Appeal reason</label><textarea name="reason"></textarea></div><button class="button secondary" type="submit">Submit appeal</button></form></article>`).join(''):'<div class="empty">No safety reports submitted.</div>'}</div></section></div>`;$('#safety-report').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await post('/v1/safety/reports',{subjectType:f.get('subjectType'),subjectId:f.get('subjectId'),reason:f.get('reason'),details:f.get('details')});notify('Safety report recorded confidentially.');await renderSafety()}catch(err){notify(err.message)}};document.querySelectorAll('.appeal-form').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await post(`/v1/safety/reports/${encodeURIComponent(e.currentTarget.dataset.id)}/appeal`,{reason:f.get('reason')});notify('Appeal recorded.');await renderSafety()}catch(err){notify(err.message)}})}
async function renderSafetyOps(){if(!await requireAuth())return;if(!has('safety.review')){main.innerHTML=errorHTML('Safety reviewer role required.');return}const items=await api('/v1/safety/review-queue');main.innerHTML=`<section class="section-head"><div><span class="eyebrow" style="color:var(--danger)">TRUST & SAFETY OPERATIONS</span><h2>Review confidential concerns with an auditable decision trail.</h2></div></section><section class="panel"><div class="list">${items.length?items.map(r=>`<article class="list-item"><header><h3>${human(r.reason)}</h3><span class="badge danger">${human(r.status)}</span></header><p>${esc(r.details||'')}</p><form class="safety-decision" data-id="${esc(r.id)}"><div class="field"><label>Reviewer note</label><textarea name="note"></textarea></div><div class="actions"><button class="button secondary" name="decision" value="triage">Triage</button><button class="button danger" name="decision" value="action">Action</button><button class="button secondary" name="decision" value="dismiss">Dismiss</button><button class="button secondary" name="decision" value="close">Close</button></div></form></article>`).join(''):'<div class="empty">Review queue clear.</div>'}</div></section>`;document.querySelectorAll('.safety-decision').forEach(form=>form.addEventListener('click',async e=>{if(!(e.target instanceof HTMLButtonElement)||e.target.name!=='decision')return;e.preventDefault();const data=new FormData(form);try{await post(`/v1/safety/reports/${encodeURIComponent(form.dataset.id)}/decision`,{decision:e.target.value,note:data.get('note')});notify('Safety decision recorded.');await renderSafetyOps()}catch(err){notify(err.message)}}))}
window.addEventListener('hashchange',()=>void route());
(async()=>{try{await handleAuthCallback();await refreshSession();renderChrome();await route()}catch(error){renderChrome();main.innerHTML=`<section class="panel"><h2>Startup error</h2>${errorHTML(error.message||String(error))}</section>`}})();
